"""Generated by Murakumo. Do not edit: change the model, then run `murakumo generate`.

Run the pipeline with __ENGINE__: every model in order, or the models of one schedule, then the tests.

    python run.py --duckdb ../../../project.duckdb --output ../../../lake
    python run.py --data orders=orders.parquet --data customers=customers.csv --output lake
    python run.py --schedule nightly --run-date 2024-01-31 --duckdb project.duckdb --output lake
"""

from __future__ import annotations

import argparse
import importlib
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))

from runtime import CONFIG, Context  # noqa: E402

ENGINE = "__ENGINE__"


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=f"Run the {CONFIG['project']} pipeline with {ENGINE}.")
    parser.add_argument("--duckdb", help="Read raw tables from this DuckDB file (its raw_* schemas).")
    parser.add_argument("--data", action="append", default=[], help="TABLE=PATH: read a raw table from a file.")
    parser.add_argument("--output", default="lake", help="Where tables and the audit tables are written.")
    parser.add_argument("--schedule", help="Build only what this schedule refreshes.")
    parser.add_argument("--run-date", help="The day cumulative tables add (YYYY-MM-DD). Default: the latest.")
    parser.add_argument("--format", default="parquet", choices=["parquet", "delta"], help="Table format (Spark).")
    args = parser.parse_args(argv)
    if args.schedule and args.schedule not in CONFIG["schedules"]:
        parser.error(f"no schedule {args.schedule!r}; there are {', '.join(CONFIG['schedules'])}")

    data = dict(item.split("=", 1) for item in args.data)
    ctx = Context(ENGINE, Path(args.output), args.duckdb, data, args.run_date, args.schedule, args.format)
    ctx.load_raw()
    chosen = set(CONFIG["schedules"][args.schedule]) if args.schedule else None
    modules = [importlib.import_module(f"models.{path.stem}") for path in sorted((HERE / "models").glob("[0-9]*.py"))]
    failed = False
    for module in modules:
        try:
            if module.KIND == "view" or chosen is None or module.NAME in chosen:
                module.build(ctx)
            elif not ctx.existing(module.NAME, module.SCHEMA, module.VIEW):
                module.build(ctx)  # not built yet by its own schedule: build it, so what reads it can run
        except Exception as exc:  # noqa: BLE001 - recorded in the run log; later models are skipped
            print(f"  {module.NAME}: failed: {' '.join(str(exc).split())[:300]}")
            failed = True
            break
    if not failed:
        for module in modules:
            for test in module.TESTS:
                ctx.test(module.NAME, *test)
    summary = ctx.finish()
    for test in ctx.tests:
        if test["status"] != "pass":
            print(f"  {test['status']}: {test['test']} ({test['failures']} rows)")
    print(
        f"{summary['status']}: {summary['models_ok']} models built, {summary['tests_passed']}/"
        f"{summary['tests_passed'] + summary['tests_failed']} tests passed. Tables are in {args.output}."
    )
    return 0 if summary["status"] == "success" else 1


if __name__ == "__main__":
    raise SystemExit(main())
